/**
 * @name Path traversal in File type handling
 * @description User-controlled file paths used in file operations without proper validation
 * @kind path-problem
 * @problem.severity error
 * @id py/click-file-path-traversal
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module FilePathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Parameters from CLI arguments
    exists(DataFlow::ParameterNode param |
      source = param and
      param.getParameter().getName() in ["filename", "path", "file", "name", "value"]
    )
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      (
        call = API::moduleImport("os").getMember("open").getACall() or
        call = API::builtin("open").getACall() or
        call = API::moduleImport("pathlib").getMember("Path").getACall()
      ) and
      sink = call.getArg(0)
    )
  }
}

module FilePathTraversalFlow = TaintTracking::Global<FilePathTraversalConfig>;
import FilePathTraversalFlow::PathGraph

from FilePathTraversalFlow::PathNode source, FilePathTraversalFlow::PathNode sink
where FilePathTraversalFlow::flowPath(source, sink) and
  sink.getNode().getLocation().getFile().getBaseName() = "types.py"
select sink.getNode(), source, sink, "Potential path traversal from $@.", source.getNode(), "user-controlled path"
